const poetryFilms=[
{id:'lushan',poemId:'lb-lushan',title:'望庐山瀑布',author:'李白',duration:60,theme:'山水奇观',tagline:'从人间飞瀑，望见九天银河',location:'庐山 · 山水想象',note:'紫烟、瀑布与银河，按诗歌意象创作；画面不代表具体历史时刻或实测地貌。',discussion:'“三千尺”与“银河落九天”，怎样把眼前风景变成浪漫想象？'},
{id:'chunwang',poemId:'df-chunwang',title:'春望',author:'杜甫',duration:62,theme:'家国之思',tagline:'一城春色，写不尽家国之思',location:'长安 · 757年春',note:'城景与人物据诗意创作，并非长安街区的考古复原。画面聚焦春花、家书与诗人的牵挂。',discussion:'同样是春天，花与鸟为什么会触发家国之悲？'},
{id:'chibi',poemId:'ss-nian',title:'念奴娇·赤壁怀古',author:'苏轼',duration:66,theme:'历史怀想',tagline:'一江风浪，与千古人物相逢',location:'黄州 · 怀古想象',note:'江上场景设于黄州；周瑜一段属于词中的历史想象。黄州赤壁不等同于通常认定的赤壁之战古战场。',discussion:'词人怎样从周瑜的意气风发，写到自己的生命感受？'}
];
let filmSceneManifest=null;
const filmMediaCache=new Map();
function prepareFilmMedia(id){if(!filmMediaCache.has(id))filmMediaCache.set(id,fetch(`assets/films/${id}.mp4?v=natural2`).then(r=>{if(!r.ok)throw Error('media');return r.blob();}).then(b=>URL.createObjectURL(b)).catch(e=>{filmMediaCache.delete(id);throw e;}));return filmMediaCache.get(id);}
function filmDuration(n){return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}
function filmCTA(poemId){const f=poetryFilms.find(f=>f.poemId===poemId);return f?`<button class="detail-film" id="detailFilm" data-film="${f.id}"><span>▶</span><div>观看这首诗的朗诵动画<small>${filmDuration(f.duration)} · 中文朗诵与配乐</small></div><em>点击播放 ↗</em></button>`:'';}
function filmCards(){return poetryFilms.map((f,i)=>`<article class="film-card"><button class="film-cover" data-play-film="${f.id}" aria-label="播放${f.title}朗诵动画"><img src="assets/films/${f.id}-poster.jpg" alt="${f.title}朗诵动画场景" loading="lazy" width="1280" height="720"><span class="film-play">▶</span><span class="film-duration">${filmDuration(f.duration)}</span></button><div class="film-card-copy"><div class="film-card-kicker">0${i+1} / ${f.theme} <span>${f.author}</span></div><h3>${f.title}</h3><p>${f.tagline}</p><button data-play-film="${f.id}">戴上耳机，走进诗中 →</button></div></article>`).join('');}
function playFilm(id){const f=poetryFilms.find(x=>x.id===id);if(!f)return;stop();showModal(`<div class="film-stage"><p class="eyebrow">诗意影院 · ${f.location}</p><h2>${f.title}<small>${f.author} · ${filmDuration(f.duration)}</small></h2><video id="poetryPlayer" controls playsinline preload="metadata" poster="assets/films/${f.id}-poster.jpg" aria-label="${f.title}中文朗诵动画"><source src="assets/films/${f.id}.mp4?v=natural2" type="video/mp4">当前浏览器暂不支持视频，请使用下方链接下载观看。</video><p id="filmStatus" class="film-status" role="status">自然语音朗诵（合成） · 轻配乐 · 字幕已内嵌</p><div class="film-chapters" id="filmChapters" aria-label="场景跳转"></div><div class="film-tools"><button id="filmFullscreen">⛶ 全屏沉浸</button><button id="filmReadPoem">读原文与赏析</button><a href="assets/films/${f.id}.mp4?v=natural2" download="${f.title}-朗诵动画.mp4">下载视频 ↓</a><a href="assets/films/${f.id}.vtt" download="${f.title}-字幕.vtt">下载字幕 ↓</a></div><div class="film-after"><h3>看完，留一个问题</h3><p>${f.discussion}</p><small>${f.note}</small></div></div>`);
const player=$('poetryPlayer');player.volume=.8;
const mediaReady=prepareFilmMedia(id).then(url=>new Promise(resolve=>{if($('poetryPlayer')!==player){resolve();return;}const t=player.currentTime;const resume=!player.paused;player.addEventListener('loadedmetadata',()=>{player.currentTime=t;if(resume)player.play().catch(()=>{});resolve();},{once:true});player.src=url;})).catch(()=>{});
const status=$('filmStatus');player.addEventListener('error',()=>{status.textContent='视频暂未加载成功，可尝试下载视频或稍后重试。'});player.addEventListener('ended',()=>{status.textContent='朗诵已结束 · 可以重看一个场景，或带着下方问题回到原文。'});const displayChapters=()=>{if(!filmSceneManifest)return;const info=filmSceneManifest.find(x=>x.id===id);if(!info)return;$('filmChapters').innerHTML=info.scenes.map((s,i)=>`<button data-seek-film="${s.start}"><span>0${i+1}</span>${s.label}</button>`).join('');document.querySelectorAll('[data-seek-film]').forEach(el=>el.onclick=async()=>{await mediaReady;if($('poetryPlayer')!==player)return;player.currentTime=+el.dataset.seekFilm;player.play().catch(()=>{});});};displayChapters();if(!filmSceneManifest)fetch('assets/films/manifest.json').then(r=>r.json()).then(data=>{filmSceneManifest=data;if($('poetryPlayer')===player)displayChapters();}).catch(()=>{});
$('filmFullscreen').onclick=()=>{if(player.requestFullscreen)player.requestFullscreen().catch(()=>{status.textContent='可使用播放器右下角的全屏按钮。'});else if(player.webkitEnterFullscreen)player.webkitEnterFullscreen();else status.textContent='可使用播放器右下角的全屏按钮。';};$('filmReadPoem').onclick=()=>{player.pause();readWork(f.poemId);};player.play().catch(()=>{status.textContent='点击播放器中的播放按钮，即可开始有声体验。'});}
function initCinema(){if($('filmCards'))$('filmCards').innerHTML=filmCards();document.querySelectorAll('[data-play-film]').forEach(el=>el.onclick=()=>playFilm(el.dataset.playFilm));$('modal').addEventListener('close',()=>{if($('poetryPlayer'))$('poetryPlayer').pause();});}
